def load_hostkey_store():
    try:
        with open(HOSTKEY_STORE, 'r', encoding='utf-8') as f:
            data = json.load(f)
            return {str(k): str(v) for k, v in data.items()}
    except Exception:
        return {}


def save_hostkey_store(data):
    try:
        os.makedirs(APP_DIR, exist_ok=True)
        with open(HOSTKEY_STORE, 'w', encoding='utf-8') as f:
            json.dump(data, f, indent=2)
    except Exception as exc:
        print(f"Failed to save host key cache: {exc}")

# ---------------- plink discovery (merged from find-plink.ps1) ----------------
def _candidate_paths(include_tortoise=False):
    pf = os.environ.get('ProgramFiles')
    pf86 = os.environ.get('ProgramFiles(x86)')
    localapp = os.environ.get('LOCALAPPDATA')
    up = os.environ.get('USERPROFILE')
    paths = [
        os.path.join(pf, 'PuTTY', 'plink.exe') if pf else None,
        os.path.join(pf86, 'PuTTY', 'plink.exe') if pf86 else None,
        os.path.join(localapp, 'Programs', 'PuTTY', 'plink.exe') if localapp else None,
        r'C:\\PuTTY\\plink.exe',
        r'C:\\Tools\\PuTTY\\plink.exe',
        r'C:\\Tools\\plink.exe',
        r'C:\\ProgramData\\chocolatey\\bin\\plink.exe',
        r'C:\\ProgramData\\chocolatey\\lib\\putty\\tools\\plink.exe',
        os.path.join(up, 'scoop', 'shims', 'plink.exe') if up else None,
        os.path.join(up, 'scoop', 'apps', 'putty', 'current', 'plink.exe') if up else None,
        os.path.join(up, 'Downloads', 'plink.exe') if up else None,
        os.path.join(up, 'Desktop', 'plink.exe') if up else None,
        os.path.join(up, 'Documents', 'plink.exe') if up else None,
        os.path.join(up, 'bin', 'plink.exe') if up else None,
        r'C:\\Portable\\PuTTY\\plink.exe',
        r'D:\\Apps\\PuTTY\\plink.exe',
        r'C:\\Windows\\System32\\plink.exe',
        r'C:\\Windows\\SysWOW64\\plink.exe',
        r'C:\\Windows\\plink.exe',
    ]
    if include_tortoise:
        paths += [
            r'C:\\Program Files\\TortoiseGit\\bin\\TortoiseGitPlink.exe',
            r'C:\\Program Files\\TortoiseSVN\\bin\\TortoisePlink.exe',
        ]
    # De-duplicate preserving order
    seen = set()
    out = []
    for p in paths:
        if not p:
            continue
        k = p.lower()
        if k not in seen:
            seen.add(k)
            out.append(p)
    return out

def _path_candidates_from_env():
    path = os.environ.get('Path') or os.environ.get('PATH') or ''
    out = []
    for d in path.split(';'):
        d = d.strip()
        if not d:
            continue
        out.append(os.path.join(d, 'plink.exe'))
    # De-dup
    seen = set(); uniq = []
    for p in out:
        k = p.lower()
        if k not in seen:
            seen.add(k)
            uniq.append(p)
    return uniq

def _deep_scan_candidates(include_tortoise=False):
    roots = []
    pf = os.environ.get('ProgramFiles'); pf86 = os.environ.get('ProgramFiles(x86)')
    localapp = os.environ.get('LOCALAPPDATA')
    up = os.environ.get('USERPROFILE')
    if pf: roots.append(pf)
    if pf86: roots.append(pf86)
    if localapp: roots.append(os.path.join(localapp, 'Programs'))
    if up:
        roots += [up, os.path.join(up, 'Downloads'), os.path.join(up, 'Desktop')]
    roots = sorted(set([r for r in roots if r and os.path.isdir(r)]))

    found = []
    targets = ['plink.exe']
    tortoise_targets = ['tortoisegitplink.exe', 'tortoiseplink.exe'] if include_tortoise else []
    for root in roots:
        for dirpath, dirnames, filenames in os.walk(root):
            names = {fn.lower(): fn for fn in filenames}
            for t in targets:
                if t in names:
                    found.append(os.path.join(dirpath, names[t]))
            for t in tortoise_targets:
                if t in names:
                    found.append(os.path.join(dirpath, names[t]))
    # De-dup
    seen = set(); uniq = []
    for p in found:
        k = p.lower()
        if k not in seen:
            seen.add(k)
            uniq.append(p)
    return uniq

def _classify_source(p):
    pl = p.replace('/', '\\').lower()
    if 'programdata\\chocolatey\\bin' in pl:
        return 'choco-shim'
    if 'programdata\\chocolatey\\lib' in pl:
        return 'choco'
    if '\\scoop\\shims' in pl:
        return 'scoop-shim'
    if '\\scoop\\apps\\putty\\current' in pl:
        return 'scoop-app'
    if '\\program files (x86)' in pl:
        return 'x86'
    if '\\program files' in pl:
        return 'x64'
    if '\\windows\\system32' in pl:
        return 'system32'
    if '\\windows\\syswow64' in pl:
        return 'syswow64'
    return 'other'

def _kind_from_name(p):
    nm = os.path.basename(p).lower()
    return 'tortoise' if nm.startswith('tortoise') else 'plink'

def resolve_plink(include_tortoise=False, deep_scan=False, all=False):
    """Locate plink.exe similar to find-plink.ps1.

    Returns best match path (str) when all=False, or a list of records
    [{'Path', 'Name', 'Kind', 'Source'}] when all=True. Returns None/[] if not found.
    """
    candidates = []
    candidates += _candidate_paths(include_tortoise=include_tortoise)
    candidates += _path_candidates_from_env()
    if deep_scan:
        candidates += _deep_scan_candidates(include_tortoise=include_tortoise)
    # De-dup while preserving order
    seen = set(); uniq = []
    for p in candidates:
        k = p.lower()
        if k not in seen:
            seen.add(k)
            uniq.append(p)
    records = []
    for p in uniq:
        try:
            if os.path.isfile(p):
                records.append({
                    'Path': p,
                    'Name': os.path.basename(p),
                    'Kind': _kind_from_name(p),
                    'Source': _classify_source(p),
                })
        except Exception:
            pass
    if not records:
        return [] if all else None
    if all:
        return sorted(records, key=lambda r: r['Path'].lower())
    # Best match: sort by (Kind, Source) alphabetically like PS script
    best = sorted(records, key=lambda r: (r['Kind'], r['Source']))[0]
    return best['Path']

def autodetect_plink():
    """Try to set PLINK_PATH automatically if current path is missing.
    Attempts: quick, include tortoise, deep scans. Returns True if found.
    """
    global PLINK_PATH
    if os.path.isfile(PLINK_PATH):
        return True
    # Quick scan
    p = resolve_plink(include_tortoise=False, deep_scan=False, all=False)
    if p and os.path.isfile(p):
        PLINK_PATH = p
        return True
    # Allow Tortoise variants
    p = resolve_plink(include_tortoise=True, deep_scan=False, all=False)
    if p and os.path.isfile(p):
        PLINK_PATH = p
        return True
    # Deep scan fallbacks
    p = resolve_plink(include_tortoise=False, deep_scan=True, all=False)
    if p and os.path.isfile(p):
        PLINK_PATH = p
        return True
    p = resolve_plink(include_tortoise=True, deep_scan=True, all=False)
    if p and os.path.isfile(p):
        PLINK_PATH = p
        return True
    return False
