def load_app_pixmap():
    """Return application pixmap decoded from embedded base64 data."""
    global _APP_ICON_PIXMAP
    if _APP_ICON_PIXMAP is not None:
        return _APP_ICON_PIXMAP
    pixmap = QtGui.QPixmap()
    try:
        data = base64.b64decode(APP_ICON_BASE64)
        pixmap.loadFromData(data)
    except Exception as exc:
        print(f"Failed to decode application pixmap: {exc}")
        pixmap = QtGui.QPixmap()
    _APP_ICON_PIXMAP = pixmap
    return pixmap


def load_app_icon():
    """Return application icon decoded from embedded base64 data."""
    global _APP_ICON
    if _APP_ICON is not None:
        return _APP_ICON
    icon = QtGui.QIcon()
    pixmap = load_app_pixmap()
    if pixmap and not pixmap.isNull():
        icon = QtGui.QIcon(pixmap)
    _APP_ICON = icon
    return icon


class LicenseManager:
    TRIAL_DAYS = 30
    LICENSE_KEY = "*****"
    SETTINGS_PREFIX = "license"

    def __init__(self):
        self.settings = QtCore.QSettings()
        self.device_id = self._get_device_id()
        self.rollback_detected = False
        self.install_ts = None
        self.expiry_ts = None
        self.activation_ts = None
        self.last_run_ts = None
        self._load_state()

    # ---------------- Persistence helpers ----------------
    def _settings_key(self, name):
        return f"{self.SETTINGS_PREFIX}/{name}"

    def _read_int(self, name):
        val = self.settings.value(self._settings_key(name))
        if val is None:
            return None
        try:
            return int(val)
        except (ValueError, TypeError):
            return None

    def _read_str(self, name):
        val = self.settings.value(self._settings_key(name))
        if val is None:
            return None
        return str(val)

    def _write_value(self, name, value):
        self.settings.setValue(self._settings_key(name), value)

    def _load_state(self):
        now = int(time.time())
        stored_device = self._read_str("device_id")
        install_ts = self._read_int("install_ts")
        expiry_ts = self._read_int("expiry_ts")
        activation_ts = self._read_int("activation_ts")
        last_run_ts = self._read_int("last_run_ts")

        # Reset state if device changed
        if stored_device and stored_device != self.device_id:
            install_ts = None
            expiry_ts = None
            activation_ts = None
            last_run_ts = None

        if not install_ts or not expiry_ts:
            install_ts = now
            expiry_ts = now + self.TRIAL_DAYS * 86400
            activation_ts = None

        # Detect clock rollback
        if last_run_ts and now < last_run_ts - 3600:
            self.rollback_detected = True
            expiry_ts = min(expiry_ts, now - 1)

        self.install_ts = install_ts
        self.expiry_ts = expiry_ts
        self.activation_ts = activation_ts
        self.last_run_ts = last_run_ts

        self._persist_state()

    def _persist_state(self):
        self._write_value("device_id", self.device_id)
        if self.install_ts:
            self._write_value("install_ts", int(self.install_ts))
        if self.expiry_ts:
            self._write_value("expiry_ts", int(self.expiry_ts))
        if self.activation_ts is not None:
            self._write_value("activation_ts", int(self.activation_ts))
        if self.last_run_ts:
            self._write_value("last_run_ts", int(self.last_run_ts))

    # ---------------- Device and time helpers ----------------
    def _get_device_id(self):
        if os.name != 'nt':
            return "UNKNOWN"
        try:
            output = subprocess.check_output(
                ["wmic", "bios", "get", "serialnumber"],
                stderr=subprocess.STDOUT,
                universal_newlines=True
            )
            parts = [line.strip() for line in output.splitlines() if line.strip()]
            if len(parts) >= 2:
                serial = parts[1]
            elif parts:
                serial = parts[0]
            else:
                serial = "UNKNOWN"
            if serial and serial.lower() != "serialnumber":
                return serial.upper()
        except Exception:
            pass
        return "UNKNOWN"

    def mark_run(self):
        now = int(time.time())
        self.last_run_ts = now
        self._persist_state()

    # ---------------- License state queries ----------------
    def is_expired(self):
        if not self.expiry_ts:
            return True
        return time.time() >= self.expiry_ts

    def is_trial(self):
        return self.activation_ts is None

    def status_label(self):
        if self.is_expired():
            return "Expired"
        if self.is_trial():
            return "Trial"
        return "Activated"

    def days_remaining(self):
        if not self.expiry_ts:
            return 0
        seconds = int(self.expiry_ts - time.time())
        if seconds <= 0:
            return 0
        return (seconds + 86399) // 86400

    def expiry_datetime(self):
        if not self.expiry_ts:
            return None
        try:
            return datetime.fromtimestamp(self.expiry_ts)
        except Exception:
            return None

    def expiry_text(self):
        dt = self.expiry_datetime()
        if not dt:
            return "Unknown"
        return dt.strftime("%Y-%m-%d %H:%M")

    # ---------------- Activation ----------------
    def activate(self, serial):
        serial = (serial or "").strip()
        if not serial:
            return False, "License key is required."
        if serial != self.LICENSE_KEY:
            return False, "Invalid license key."
        now = int(time.time())
        self.activation_ts = now
        self.expiry_ts = now + self.TRIAL_DAYS * 86400
        if not self.install_ts:
            self.install_ts = now
        self._persist_state()
        return True, f"Activation successful. License valid until {self.expiry_text()}."

    def reset_trial(self):
        now = int(time.time())
        self.install_ts = now
        self.expiry_ts = now + self.TRIAL_DAYS * 86400
        self.activation_ts = None
        self._persist_state()


# Startup configuration helpers
def apply_env_overrides():
    """Apply environment overrides for config values (e.g., PLINK_PATH)."""
    global PLINK_PATH
    env_plink = os.environ.get("PLINK_PATH") or os.environ.get("FXM_PLINK_PATH")
    if env_plink:
        PLINK_PATH = env_plink


def validate_config():
    """Validate essential configuration and return (ok, error_message)."""
    errors = []
    if not os.path.isfile(PLINK_PATH):
        if not autodetect_plink():
            errors.append(f"plink.exe not found at: {PLINK_PATH}")
    if not LOCATIONS or not isinstance(LOCATIONS, dict):
        errors.append("No locations configured.")
    else:
        for loc, info in LOCATIONS.items():
            ssh = info.get("ssh", {})
            sources = info.get("sources", [])
            if not (isinstance(ssh, dict) and all(ssh.get(k) for k in ("host", "user", "pw"))):
                errors.append(f"Invalid SSH config for location: {loc}")
            if not (isinstance(sources, list) and sources):
                errors.append(f"No sources configured for location: {loc}")
    return (len(errors) == 0, "\n".join(errors))


class FXMSoundEngine:
    """Configurable sound engine supporting Windows beep and WAV playback."""

    def __init__(self):
        self._winsound = None
        self._wav_cache = {}
        self._last_play = {"warning": 0.0, "error": 0.0}
        try:
            import winsound  # type: ignore
            self._winsound = winsound
        except Exception:
            self._winsound = None

    def _play_beep(self, frequency, duration_ms, repeat=1, gap=0.1):
        for _ in range(max(1, repeat)):
            if self._winsound:
                self._winsound.Beep(int(frequency), int(duration_ms))
            else:
                print('\a')
                time.sleep(duration_ms / 1000.0)
            if repeat > 1:
                time.sleep(max(0.0, gap))

    def _play_wav(self, path):
        if not path:
            return False
        if not os.path.isfile(path):
            print(f"[Sound] WAV file not found: {path}")
            return False
        if path not in self._wav_cache:
            self._wav_cache[path] = QSound(path)
        self._wav_cache[path].play()
        return True

    def play(self, alert_type, settings, *, force=False):
        """Play sound for alert_type using provided settings."""
        alert_type = "warning" if alert_type == "warning" else "error"
        cooldown = settings.get('warning_cooldown', 1) if alert_type == "warning" else settings.get('error_cooldown', 1)
        now = time.time()
        if not force and cooldown > 0 and (now - self._last_play.get(alert_type, 0)) < cooldown:
            return

        mode = settings.get('sound_mode', 'beep')
        if mode == 'wav':
            key = 'sound_wav_warning' if alert_type == 'warning' else 'sound_wav_error'
            path = settings.get(key, '')
            played = self._play_wav(path)
            if not played:
                # Fall back to beep if WAV missing or failed
                mode = 'beep'
        if mode == 'beep':
            if alert_type == 'error':
                profile = settings.get('sound_beep_error', {'freq': 950, 'duration': 350, 'repeat': 3, 'gap': 0.1})
            else:
                profile = settings.get('sound_beep_warning', {'freq': 650, 'duration': 180, 'repeat': 1, 'gap': 0.0})
            self._play_beep(profile.get('freq', 900), profile.get('duration', 300), profile.get('repeat', 1), profile.get('gap', 0.1))

        self._last_play[alert_type] = time.time()

class SoundManager:
    """Alarm sound manager"""
    
    def __init__(self):
        self.last_warning_time = 0
        self.last_error_time = 0
        self.warning_cooldown = 1  # 10 seconds cooldown for warning
        self.error_cooldown = 1     # 5 seconds cooldown for error
        self.alarm_enabled = True
        
    def play_warning_sound(self):
        """Play a warning alarm sound"""
        if not self.alarm_enabled:
            return
            
        current_time = time.time()
        if current_time - self.last_warning_time >= self.warning_cooldown:
            # Generate beep sound using system beep
            print('\a')  # System beep
            self.last_warning_time = current_time
            print("Warning alarm: ping is high!")
    
    def play_error_sound(self):
        """Play an error alarm sound"""
        if not self.alarm_enabled:
            return
            
        current_time = time.time()
        if current_time - self.last_error_time >= self.error_cooldown:
            # Generate more urgent beep
            for _ in range(3):
                print('\a')
                time.sleep(0.1)
            self.last_error_time = current_time
            print("Error alarm: connection lost!")

# Worker thread that runs plink and streams output
class SSHProcessWorker(QtCore.QThread):
    line_received = QtCore.pyqtSignal(str, str)     # source_ip, line
    status_update = QtCore.pyqtSignal(str, str)     # source_ip, status
    ping_result = QtCore.pyqtSignal(str, float)     # source_ip, ping_time

    def __init__(self, plink_path, ssh_host, ssh_user, ssh_pw, source_ip, dest_ip, mode="ping", parent=None, hostkey=None):
        super().__init__(parent)
        self.plink_path = plink_path
        self.ssh_host = ssh_host
        self.ssh_user = ssh_user
        self.ssh_pw = ssh_pw
        self.source_ip = source_ip
        self.dest_ip = dest_ip
        self.mode = mode  # "ping" or "mtr"
        self.hostkey = hostkey
        self._stopped = False
        self.process = None
        self._local_seq = 0

    def stop(self):
        self._stopped = True
        if self.process:
            try:
                self.process.terminate()
            except:
                pass

    def extract_ping_time(self, line):
        """Extract ping time from ping output line"""
        if "time=" in line:
            match = re.search(r'time=([\d.]+)\s*ms', line)
            if match:
                return float(match.group(1))
        return None

    def run(self):
        while not self._stopped:
            base_cmd = [
                self.plink_path,
                "-batch",
                "-ssh",
                f"{self.ssh_user}@{self.ssh_host}"
            ]
            if self.hostkey:
                base_cmd.extend(["-hostkey", self.hostkey])
            base_cmd.extend(["-pw", self.ssh_pw])

            if self.mode == "ping":
                cycle_mark = "__FXM_CYCLE__"
                remote = (
                    f"sh -c \"while true; do ping -n -c 1 -W 1 -I {self.source_ip} {self.dest_ip}; echo {cycle_mark}; sleep 1; done\""
                )
                cmd = base_cmd + [remote]
                self.status_update.emit(self.source_ip, f"Monitoring ping -> {self.dest_ip}")
            elif self.mode == "mtr":
                cycles = 5
                cmd = base_cmd + [f'mtr --report --report-cycles {cycles} --address {self.source_ip} {self.dest_ip}']
                self.status_update.emit(self.source_ip, f"Starting mtr({cycles}) -> {self.dest_ip}")
            else:
                self.status_update.emit(self.source_ip, f"Unknown mode {self.mode}")
                return

            try:
                # Fix: prevent CMD windows from appearing
                if os.name == 'nt':  # Windows only
                    startupinfo = subprocess.STARTUPINFO()
                    startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
                    startupinfo.wShowWindow = 0
                    self.process = subprocess.Popen(cmd, 
                                                  stdout=subprocess.PIPE, 
                                                  stderr=subprocess.STDOUT, 
                                                  bufsize=1, 
                                                  universal_newlines=True,
                                                  startupinfo=startupinfo,
                                                  creationflags=subprocess.CREATE_NO_WINDOW)
                else:
                    self.process = subprocess.Popen(cmd, 
                                                  stdout=subprocess.PIPE, 
                                                  stderr=subprocess.STDOUT, 
                                                  bufsize=1, 
                                                  universal_newlines=True)
            except Exception as e:
                self.status_update.emit(self.source_ip, f"Failed to start plink: {e}")
                time.sleep(3)
                continue

            try:
                if self.mode == "ping":
                    # Persistent parsing by cycles
                    cycle_seq = self._local_seq + 1
                    got_reply = False
                    while not self._stopped:
                        raw = self.process.stdout.readline()
                        if raw == '':
                            break
                        line = raw.rstrip("\n")
                        if not line:
                            continue
                        if line.strip() == cycle_mark:
                            if not got_reply:
                                self.line_received.emit(self.source_ip, "Ping Timeout")
                            # finalize and advance sequence
                            self._local_seq = cycle_seq
                            cycle_seq = self._local_seq + 1
                            got_reply = False
                            continue
                        lwr = line.lower()
                        # Filter noise
                        if (
                            lwr.startswith("ping ")
                            or lwr.startswith("--- ")
                            or " packets transmitted" in lwr
                            or lwr.startswith("rtt ")
                            or "rtt min/avg/max" in lwr
                            or "round-trip min/avg/max" in lwr
                            or "round-trip time" in lwr
                        ):
                            continue
                        if "bytes from" in lwr:
                            out = re.sub(r"icmp_seq=\d+", f"icmp_seq={cycle_seq}", line)
                            self.line_received.emit(self.source_ip, out)
                            ping_time = self.extract_ping_time(line)
                            if ping_time is not None:
                                self.ping_result.emit(self.source_ip, ping_time)
                            got_reply = True
                        else:
                            # pass through diagnostics (e.g., unknown host)
                            self.line_received.emit(self.source_ip, line)
                else:
                    for line in iter(self.process.stdout.readline, ''):
                        if self._stopped:
                            break
                        if line.strip():
                            self.line_received.emit(self.source_ip, line.rstrip("\n"))
                            if self.mode == "ping":
                                ping_time = self.extract_ping_time(line)
                                if ping_time is not None:
                                    self.ping_result.emit(self.source_ip, ping_time)

                # Wait only for short-lived processes (e.g., mtr)
                if self.mode != "ping":
                    self.process.wait()
            except Exception as e:
                self.status_update.emit(self.source_ip, f"Error reading output: {e}")

            try:
                if self.process:
                    self.process.kill()
            except:
                pass

            if self._stopped:
                self.status_update.emit(self.source_ip, "Stopped")
                break

            return_code = self.process.returncode if self.process else None
            if return_code is not None and return_code != 0:
                self.status_update.emit(self.source_ip, f"error: {self.mode} exit code {return_code}")
                self.line_received.emit(self.source_ip, f"{self.mode} exited with code {return_code}")

            if self._stopped:
                self.status_update.emit(self.source_ip, "Stopped")
                break

            time.sleep(2)


# Custom widget per source that supports drag & drop within the grid
class SourceWidget(QtWidgets.QFrame):
    drag_started = QtCore.pyqtSignal(object)  # self
    drag_ended = QtCore.pyqtSignal(object, QtCore.QPoint)  # self, globalDropPos

    def __init__(self, loc_name, source_ip, ssh_info, main_window):
        super().__init__()
        self.loc_name = loc_name
        self.source_ip = source_ip
        self.ssh_info = ssh_info
        self.main_window = main_window  # Reference to main window for settings
        self.user_font_size = None
        self.current_ping = 0.0
        self.packet_loss = 0.0
        self.status = "idle"
        self.last_ping_state = "good"  # Track last state for sound alerts
        
        # Set initial style
        self.setFrameShape(QtWidgets.QFrame.Box)
        self.setLineWidth(2)
        self.setMidLineWidth(0)
        self.setAutoFillBackground(True)
        self.update_style()
        
        v = QtWidgets.QVBoxLayout(self)
        v.setSpacing(4)
        v.setContentsMargins(6, 6, 6, 6)

        # Header
        title = QtWidgets.QLabel(f"{loc_name} | {source_ip}")
        title.setAlignment(QtCore.Qt.AlignCenter)
        title.setStyleSheet("font-weight: bold; font-size: 11px; color: #FFFFFF; background-color: transparent;")
        v.addWidget(title)

        # Ping display
        self.ping_label = QtWidgets.QLabel("Ping: - ms")
        self.ping_label.setAlignment(QtCore.Qt.AlignCenter)
        self.ping_label.setStyleSheet("font-size: 10px; font-weight: bold; color: #FFFFFF;")
        v.addWidget(self.ping_label)

        self.text = QtWidgets.QPlainTextEdit()
        self.text.setReadOnly(True)
        font = QtGui.QFont("Consolas", 9)
        self.text.setFont(font)
        self.text.setStyleSheet("background-color: #1E1E1E; color: #FFFFFF; border: 1px solid #444;")
        # Keep only the most recent N lines to prevent memory growth
        self.text.document().setMaximumBlockCount(800)
        v.addWidget(self.text)

        self.status_label = QtWidgets.QLabel("Status: idle")
        self.status_label.setStyleSheet("color: #CCCCCC; font-size: 9px; font-weight: bold;")
        v.addWidget(self.status_label)

        self.setMinimumSize(280, 180)
        self.setMaximumWidth(800)

        self._dragging = False
        self._drag_pos = None

    def get_current_state(self):
        """Get current ping state for sound alerts"""
        settings = self.main_window.settings
        
        if self.status in ["timeout", "error"]:
            return "error"
        elif self.status in ["stopped", "cleared"]:
            return "default"
        elif self.current_ping >= settings['warning_threshold']:
            return "warning"
        elif self.current_ping >= settings['good_threshold']:
            return "medium"
        elif self.status == "connected" and self.current_ping > 0:
            return "good"
        else:
            return "default"

    def update_style(self):
        """Update widget style based on ping status"""
        settings = self.main_window.settings
        
        current_state = self.get_current_state()
        
        # Notify main window about state change for sound handling
        self.main_window.handle_ping_state(self.source_ip, self.last_ping_state, current_state)

        self.last_ping_state = current_state
        
        if current_state == "error":
            # Use error color from settings
            color = settings['error_bg_color']
            border_color = settings['error_border_color']
        elif current_state == "warning":
            # Use warning color for high ping
            color = settings['warning_bg_color']
            border_color = settings['warning_border_color']
        elif current_state == "medium":
            # Use lighter medium color (configurable factor)
            base = settings['medium_bg_color']
            factor = settings.get('medium_light_factor', 1.3)
            color = self.main_window.adjust_brightness(base, factor)
            border_color = settings['medium_border_color']
        elif current_state == "good":
            # Use good color for good ping
            color = settings['good_bg_color']
            border_color = settings['good_border_color']
        else:
            # Default color
            color = settings['default_bg_color']
            border_color = settings['default_border_color']

        self.setStyleSheet(f"""
            SourceWidget {{
                background-color: {color};
                border: 2px solid {border_color};
                border-radius: 5px;
            }}
        """)

    def append_line(self, line):
        self.text.appendPlainText(line)
        
        # Update status based on content
        line_lower = line.lower()
        if any(keyword in line_lower for keyword in (
            "timeout",
            "time out",
            "no answer yet",
            "destination host unreachable",
            "destination net unreachable",
            "network is unreachable",
            "host unreachable",
            "unknown host",
            "name or service not known",
            "bad address",
            "cannot resolve",
            "failed to reach",
            "100% packet loss",
            "100.0% packet loss",
            "fatal error",
            "connection refused",
            "temporary failure in name resolution"
        )):
            self.status = "error"
        elif "loss%" in line_lower and ("100.0" in line_lower or "100%" in line_lower):
            self.status = "error"
        elif "connected" in line_lower or "bytes from" in line_lower:
            self.status = "connected"
        elif "error" in line_lower:
            self.status = "error"
            
        self.update_style()
        
        # Auto-scroll; line limit handled by maximumBlockCount
        self.text.verticalScrollBar().setValue(self.text.verticalScrollBar().maximum())

    def set_ping_time(self, ping_time):
        """Update ping time and color coding"""
        self.current_ping = ping_time
        self.ping_label.setText(f"Ping: {ping_time:.1f} ms")
        
        settings = self.main_window.settings
        
        # Update color based on ping time and settings
        if ping_time >= settings['warning_threshold']:
            self.ping_label.setStyleSheet(f"font-size: 10px; font-weight: bold; color: {settings['warning_text_color']};")
        elif ping_time >= settings['good_threshold']:
            self.ping_label.setStyleSheet(f"font-size: 10px; font-weight: bold; color: {settings['medium_text_color']};")
        else:
            self.ping_label.setStyleSheet(f"font-size: 10px; font-weight: bold; color: {settings['good_text_color']};")
            
        self.update_style()

    def set_status(self, status):
        self.status = status
        self.status_label.setText(f"Status: {status}")
        self.update_style()

    def set_font_size(self, size):
        self.user_font_size = size
        self.apply_text_font()

    def apply_text_font(self):
        """Apply current font size to the text area without triggering resize events."""
        h = max(80, self.height())
        if self.user_font_size:
            new_point = self.user_font_size
        else:
            new_point = max(7, int(h / 20))
        f = self.text.font()
        f.setPointSize(new_point)
        self.text.setFont(f)

    def mousePressEvent(self, event):
        if event.button() == QtCore.Qt.LeftButton:
            self._dragging = True
            self._drag_pos = event.globalPos()
            self.setCursor(QtCore.Qt.ClosedHandCursor)
            self.raise_()
            self.drag_started.emit(self)
            event.accept()
        else:
            super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self._dragging:
            delta = event.globalPos() - self._drag_pos
            self._drag_pos = event.globalPos()
            parent = self.parentWidget()
            if parent:
                new_pos = self.mapToParent(delta)
                self.move(self.x() + delta.x(), self.y() + delta.y())
            event.accept()
        else:
            super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if self._dragging:
            self._dragging = False
            self.setCursor(QtCore.Qt.ArrowCursor)
            self.drag_ended.emit(self, event.globalPos())
            event.accept()
        else:
            super().mouseReleaseEvent(event)

    def resizeEvent(self, ev):
        self.apply_text_font()
        super().resizeEvent(ev)


class HostKeyWorker(QtCore.QThread):
    progress = QtCore.pyqtSignal(int, int, str)  # current, total, message
    result = QtCore.pyqtSignal(dict)             # {'summary': {...}, 'hostkeys': {...}}

    def __init__(self, plink_path, locations, known_keys=None, timeout=15):
        super().__init__()
        self.plink_path = plink_path
        self.locations = locations
        self.timeout = timeout
        self._stop = False
        self.known_keys = dict(known_keys or {})

    def stop(self):
        self._stop = True

    def run(self):
        seen = set()
        hosts = []
        for info in self.locations.values():
            ssh = info.get("ssh", {})
            host = ssh.get("host"); user = ssh.get("user"); pw = ssh.get("pw")
            if host and user and pw:
                key = (host, user)
                if key not in seen:
                    seen.add(key)
                    hosts.append((host, user, pw))

        total = len(hosts)
        summary = {"new": 0, "unchanged": 0, "updated": 0, "failed": 0, "cancelled": 0}
        collected = {}

        if total == 0:
            self.result.emit({"summary": summary, "hostkeys": collected})
            return

        for idx, (host, user, pw) in enumerate(hosts, start=1):
            if self._stop:
                summary["cancelled"] += total - idx + 1
                break
            self.progress.emit(idx, total, f"Connecting to {host} ...")
            try:
                status, fingerprint = self._fetch_hostkey(host, user, pw, self.known_keys.get(host))
            except Exception:
                status, fingerprint = ("failed", None)

            if status == "cancelled":
                summary["cancelled"] += total - idx + 1
                break
            if status in ("new", "updated", "unchanged") and fingerprint:
                collected[host] = fingerprint
            summary[status] = summary.get(status, 0) + 1

        self.result.emit({"summary": summary, "hostkeys": collected})

    def _build_plink_cmd(self, base_args):
        cmd = [self.plink_path]
        cmd.extend(base_args)
        return cmd

    def _fetch_hostkey(self, host, user, pw, existing_key=None):
        base_args = [
            "-v",
            "-batch",
            "-ssh",
            f"{user}@{host}",
            "-pw", pw,
            "exit"
        ]
        cmd = self._build_plink_cmd(base_args)

        startupinfo = None
        creationflags = 0
        if os.name == 'nt':
            startupinfo = subprocess.STARTUPINFO()
            startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
            startupinfo.wShowWindow = 0
            creationflags = subprocess.CREATE_NO_WINDOW

        proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                universal_newlines=True, startupinfo=startupinfo,
                                creationflags=creationflags)

        fingerprint = None
        start_time = time.time()
        try:
            while True:
                if self._stop:
                    return ("cancelled", None)
                line = proc.stdout.readline()
                if not line:
                    break
                match = re.search(r"SHA256:[A-Za-z0-9+/=]+", line)
                if match:
                    fingerprint = match.group(0)
                if time.time() - start_time > self.timeout:
                    break
            try:
                proc.wait(timeout=5)
            except Exception:
                proc.kill()
        finally:
            try:
                proc.kill()
            except Exception:
                pass

        if self._stop:
            return ("cancelled", None)
        if not fingerprint:
            return ("failed", None)

        if not self._verify_hostkey(host, user, pw, fingerprint):
            return ("failed", None)

        if not existing_key:
            return ("new", fingerprint)
        if existing_key == fingerprint:
            return ("unchanged", fingerprint)
        return ("updated", fingerprint)

    def _verify_hostkey(self, host, user, pw, fingerprint):
        base_args = [
            "-batch",
            "-ssh",
            f"{user}@{host}",
            "-hostkey", fingerprint,
            "-pw", pw,
            "exit"
        ]
        cmd = self._build_plink_cmd(base_args)

        startupinfo = None
        creationflags = 0
        if os.name == 'nt':
            startupinfo = subprocess.STARTUPINFO()
            startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
            startupinfo.wShowWindow = 0
            creationflags = subprocess.CREATE_NO_WINDOW

        proc = None
        try:
            proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                    universal_newlines=True, startupinfo=startupinfo,
                                    creationflags=creationflags)
            proc.wait(timeout=max(5, self.timeout // 2))
            return proc.returncode == 0
        except Exception:
            return False
        finally:
            if proc and proc.poll() is None:
                try:
                    proc.kill()
                except Exception:
                    pass


